def min_operations(a, b):
    if a == b:
        return 0
    if a > b:
        a, b = b, a
    delta = b - a
    operations = 0
    i = 1
    while delta > 0:
        if delta >= i:
            delta -= i
            operations += 1
        i += 1
    return operations

